        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a
        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1

    by_email = {}
    by_phone_and_last_name = {}

    for i, row in enumerate(normalized):
        if row["email"]:
            previous = by_email.get(row["email"])
            if previous is None:
                by_email[row["email"]] = i
            else:
                union(i, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = by_phone_and_last_name.get(key)
            if previous is None:
                by_phone_and_last_name[key] = i
            else:
                union(i, previous)

    groups = {}
    for i, row in enumerate(normalized):
        groups.setdefault(find(i), []).append(row)

    def pick_field(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""
        chosen = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated"],
                -row["input_index"],
            ),
        )
        return chosen[field]

    output = []
    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["input_index"] for row in group),
    )

    for group in ordered_groups:
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated"] for row in group)

        output.append({
            "first_name": pick_field(group, "first_name"),
            "last_name": pick_field(group, "last_name"),
            "zip": pick_field(group, "zip"),
            "email": pick_field(group, "email"),
            "phone": pick_field(group, "phone"),
            "source": pick_field(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return output
